<?php elseif ($tab==='services'): ?><details class="panel"><summary>Apply as a service provider</summary><p class="tiny">Applications require administrator approval before appearing in the directory.</p><form action="/dashboard/action" method="post"><?= dashboardHidden('provider_apply',0,$tab) ?><label class="field"><span>Provider name</span><input name="name" required></label><label class="field"><span>Service category</span><input name="category" required placeholder="Photography, staging, moving…"></label><label class="field"><span>Details for administrator review</span><textarea name="details" minlength="10" required></textarea></label><button class="button small">Submit provider application</button></form></details>
